root <- Sys.getenv('ANALYSIS_ROOT',unset=normalizePath('260925_Re',winslash='/',mustWork=FALSE)); lib <- file.path(root,'runtime/r-library')
rt <- shortPathName(file.path(root,'runtime/rtools45-portable/{app}'))
dir.create(file.path(rt,'tmp'),showWarnings=FALSE)
Sys.setenv(RTOOLS45_HOME=rt,PATH=paste(file.path(rt,'usr/bin'),file.path(rt,'x86_64-w64-mingw32.static.posix/bin'),Sys.getenv('PATH'),sep=.Platform$path.sep))
mv <- file.path(root,'runtime/Makevars.bayesprism')
tc <- gsub('\\\\','/',file.path(rt,'x86_64-w64-mingw32.static.posix'))
writeLines(c(paste0('CXX = "',tc,'/bin/g++.exe" -no-canonical-prefixes -fno-canonical-system-headers'),paste0('CXX17 = "',tc,'/bin/g++.exe" -no-canonical-prefixes -fno-canonical-system-headers'),paste0('CC = "',tc,'/bin/gcc.exe" -no-canonical-prefixes'),'CXX17STD = -std=gnu++17',paste0('PKG_CPPFLAGS = -I"',tc,'/lib/gcc/x86_64-w64-mingw32.static.posix/14.3.0/include/c++/x86_64-w64-mingw32.static.posix"')),mv)
Sys.setenv(R_MAKEVARS_USER=mv)
cat('\nexport PATH := /usr/bin:/x86_64-w64-mingw32.static.posix/bin:$(PATH)\nNM = /x86_64-w64-mingw32.static.posix/bin/nm\nSED = /usr/bin/sed\nRM = /usr/bin/rm -f\n',file=mv,append=TRUE)
Sys.setenv(COMPILER_PATH=paste0(tc,'/bin'),LIBRARY_PATH=paste0(tc,'/lib'))
cat('Rtools',rt,'\n');print(Sys.which(c('make','g++')))
if (!requireNamespace('bluster',quietly=TRUE)) install.packages(file.path(root,'runtime/installers/r-packages/bluster_1.20.0.tar.gz'),repos=NULL,type='source',lib=lib,INSTALL_opts='--no-multiarch')
stopifnot(requireNamespace('bluster',quietly=TRUE))
install.packages(file.path(root,'runtime/BayesPrism-source/BayesPrism'),repos=NULL,type='source',lib=lib,INSTALL_opts='--no-multiarch')
library(BayesPrism);print(packageVersion('BayesPrism'));writeLines(capture.output(sessionInfo()),file.path(root,'runtime/BayesPrism_sessionInfo.txt'))
